"""Fonte editorial da unidade 1.1. Gera JSON; não é executado pelo aplicativo."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]

def text(body, title=None):
    b={'type':'text','body':body}
    if title:b['title']=title
    return b

def call(title, body, tone='tip'):return {'type':'callout','title':title,'body':body,'tone':tone}
def listing(title, items):return {'type':'list','title':title,'items':items}
def anim(kind,title,caption):return {'type':'animation','kind':kind,'title':title,'caption':caption}
def photo(file,title,caption,credit):return {'type':'photo','src':'media/'+file,'title':title,'caption':caption,'credit':credit}
questions=[]; lessons=[]
def q(id,lesson,stem,options,answer,feedback,tag,final=False):
    questions.append({'id':id,'lesson':lesson,'stem':stem,'options':options,'answer':answer,'feedback':feedback,'tag':tag,'pool':'final' if final else 'lesson','type':'truefalse' if len(options)==2 else 'single'})
def lesson(id,title,kicker,minutes,blocks,summary,practice=None):
    d={'id':id,'title':title,'kicker':kicker,'minutes':minutes,'blocks':blocks,'summary':summary}
    if practice:d['practice']=practice
    lessons.append(d)

lesson('l01','Para que aprender Geografia?','Comece pelo cotidiano',7,[
 text('Imagine duas comunidades próximas de um rio. Uma dispõe de saneamento e acesso seguro à escola. Na outra, uma chuva intensa interrompe o caminho dos estudantes. Saber o nome do rio é útil, mas não explica essa diferença. Precisamos relacionar natureza, sociedade, decisões públicas e formas de ocupar o espaço.'),
 anim('inequality','Uma chuva, duas condições','Mude a infraestrutura da cena e observe como o mesmo evento natural pode ter efeitos diferentes. Cena hipotética: não representa um diagnóstico de uma comunidade real.'),
 text('A Geografia escolar ajuda o estudante a interpretar onde os fenômenos acontecem, por que se distribuem de determinado modo e como lugares diferentes se relacionam. É uma formação para compreender e agir no mundo. O conteúdo não se resume a capitais, relevo ou localização.'),
 call('Sua pergunta de partida','Como uma maneira de interpretar o espaço influencia uma aula de Geografia? Essa pergunta acompanha toda a unidade.'),
 listing('Ao final desta unidade, você conseguirá', ['Distinguir uma teoria geográfica de uma técnica de ensino.', 'Reconhecer perspectivas tradicionais, quantitativas, críticas, humanísticas e culturais.', 'Relacionar essas perspectivas a decisões de ensino, sem reduzir a aula a rótulos.', 'Construir um argumento curto sobre ensino de Geografia com conceito e exemplo.'])
], 'Geografia escolar articula conhecimentos para interpretar relações espaciais. Localizar é um passo; explicar e relacionar também são necessários.')
q('q01','l01','Qual pergunta amplia uma aula sobre uma cheia de rio para uma análise geográfica?', ['Qual é o nome do rio?', 'Como ocupação, infraestrutura e chuva se relacionam com a exposição à cheia?', 'Quantas letras tem o nome da comunidade?', 'Qual é a única causa natural de todos os problemas da comunidade?'],1, ['Localizar e nomear ajudam, mas essa pergunta sozinha não relaciona processos.', 'Você articulou componentes naturais e sociais e perguntou pelas relações espaciais. Isso evita explicar todo o problema apenas pela chuva.', 'A contagem de letras não esclarece a organização do espaço.', 'O enunciado procura uma causa única e ignora decisões sociais. A análise precisa examinar a combinação de condições.'],'raciocínio geográfico')
q('q02','l01','Conhecer nomes e localizações é suficiente para desenvolver pensamento geográfico.', ['Verdadeiro','Falso'],1,['Esses conhecimentos ajudam, mas faltam relações, explicações e interpretação de processos.', 'Localização e vocabulário são pontos de apoio. Pensar geograficamente exige relacioná-los a processos e a outras escalas.'],'raciocínio geográfico')
q('q03','l01','Uma explicação afirma: “A chuva atinge todos, portanto todos sofrem os mesmos impactos”. Qual limite ela apresenta?', ['Desconsidera condições desiguais de ocupação e proteção.', 'Considera demais a infraestrutura.', 'Reconhece todas as relações relevantes.', 'Demonstra que o espaço não influencia a vida.'],0,['O mesmo evento pode encontrar moradias, acessos e serviços diferentes. A distribuição dessas condições deve entrar na análise.', 'A explicação não considera infraestrutura; justamente por isso é incompleta.', 'Ela toma uma condição em comum como se todas as demais também fossem iguais.', 'O espaço e suas formas de ocupação ajudam a compreender os impactos.'],'sociedade e natureza')

lesson('l02','Teoria, método e recurso','Entenda os termos do edital',8,[
 text('Concepção teórica é a maneira de compreender o objeto estudado: o que consideramos importante e como explicamos suas relações. Uma perspectiva crítica, por exemplo, pergunta como relações de poder e produção participam da organização do espaço.'),
 text('Método é o caminho de investigação e interpretação. Inclui como formular problemas, construir relações e avaliar explicações. Metodologia de ensino organiza as condições para o aluno aprender: objetivos, perguntas, atividades, mediação e avaliação.'),
 {'type':'table','title':'Três decisões diferentes','headers':['Decisão','Exemplo'],'rows':[['O que quero compreender?','Desigualdade no acesso à cidade.'],['Como vou investigar e interpretar?','Relacionar moradia, transporte, renda e políticas em diferentes escalas.'],['Como vou ensinar?','Comparar mapas e relatos, formular hipóteses e discutir evidências.']]},
 call('Um recurso não define a concepção','Mapa, aula expositiva, fotografia, aplicativo e saída de campo podem servir a perspectivas distintas. O que diferencia a proposta é o problema, a explicação construída e a participação intelectual do estudante.'),
 text('Epistemologia é a reflexão sobre como o conhecimento é produzido, justificado e limitado. Paradigma é um conjunto de referências que orienta perguntas e explicações em uma comunidade científica. Aqui, esses termos ajudam a entender as correntes sem exigir decorar definições isoladas.')
], 'Pergunte sempre: qual interpretação do espaço orienta a aula, como a investigação é feita e o que o aluno precisa aprender?',{'type':'match','title':'Associe a decisão ao seu papel','pairs':[['Interpretar relações de poder no território','Concepção teórica'],['Relacionar processos e confrontar explicações','Método de investigação'],['Organizar perguntas e intervenções do professor','Metodologia de ensino'],['Utilizar um mapa digital','Recurso didático']]})
q('q04','l02','Uma professora usa mapas digitais. É possível identificar sua concepção geográfica apenas por esse recurso?', ['Sim; todo mapa digital é crítico.', 'Sim; toda tecnologia é quantitativa.', 'Não; é necessário examinar o problema e a interpretação construída.', 'Não; mapas digitais não podem ensinar Geografia.'],2,['Um mapa digital pode apoiar diferentes interpretações. O recurso não decide sozinho a concepção.', 'Tecnologias podem medir dados e também apoiar análises críticas, culturais ou do lugar vivido.', 'É preciso examinar objetivos, perguntas, relações explicadas e mediação. A tecnologia, isoladamente, não informa esses elementos.', 'Mapas digitais podem ensinar Geografia quando integrados a objetivos e atividades adequados.'],'teoria e método')
q('q05','l02','Qual decisão se aproxima mais de uma escolha teórica?', ['Escolher o tamanho da fonte.', 'Interpretar a cidade como produção social marcada por desigualdades.', 'Fixar a duração de um vídeo.', 'Trocar a cor de um mapa.'],1,['A fonte é uma decisão de apresentação e acessibilidade, não uma interpretação do espaço.', 'Essa escolha afirma uma maneira de compreender a organização da cidade e orienta as perguntas da investigação.', 'A duração é uma decisão de organização do recurso.', 'A cor pode melhorar a comunicação, mas não define, por si, a concepção geográfica.'],'teoria e método')
q('q06','l02','Uma aula expositiva é sempre incompatível com uma proposta crítica.', ['Verdadeiro','Falso'],1,['A forma expositiva não determina sozinha a concepção. Ela pode introduzir conceitos que serão mobilizados em uma investigação crítica.', 'Uma exposição pode oferecer referências importantes. É preciso avaliar seu conteúdo, propósito e articulação com a atividade intelectual dos estudantes.'],'teoria e método')

lesson('l03','A formação da Geografia moderna','Natureza e ação humana',10,[
 text('Na consolidação da Geografia moderna, especialmente no século XIX, cresceram os estudos sistemáticos de relações entre sociedades e natureza, distribuição de fenômenos e diferenças entre regiões. Esses estudos ocorreram em contextos de expansão dos Estados nacionais e de projetos coloniais. Não formavam uma única teoria homogênea.'),
 text('Determinismo ambiental é o nome usual de explicações que atribuem ao meio natural um poder decisivo sobre características sociais. É problemático transformar clima ou relevo em destino das populações. A tradição associou esse debate a Friedrich Ratzel, mas sua obra é mais complexa do que a caricatura de que o clima explica tudo.'),
 anim('river','O rio não decide sozinho','Alterne entre uma explicação que transforma o rio em destino e outra que considera escolhas, técnicas e organização social.'),
 text('Possibilismo é a designação tradicionalmente associada à escola francesa e a Paul Vidal de la Blache. Destaca que o meio oferece condições e possibilidades, mobilizadas por grupos humanos por meio de práticas e técnicas. “Gêneros de vida” ajuda a pensar modos de vida historicamente constituídos. Isso não significa liberdade ilimitada diante da natureza.'),
 call('Como isso aparece em uma questão','“O clima torna inevitável o atraso” é uma pista determinista e naturaliza relações sociais. “Grupos usam técnicas distintas diante de condições semelhantes” destaca mediações e possibilidades.'),
 text('Na escola, não basta reconhecer o rótulo. Explique por que uma justificativa é inadequada: ela apaga história, relações de poder, técnicas e escolhas políticas. A natureza condiciona a vida; não autoriza hierarquizar povos nem declarar inevitáveis as desigualdades.')
], 'Condições naturais importam, mas não determinam sozinhas sociedades. Determinismo e possibilismo são referências históricas, não descrições completas das obras de seus autores.')
q('q07','l03','“O clima quente torna inevitável que uma sociedade seja pouco desenvolvida”. Qual problema está presente?', ['Naturalização de uma condição social por uma explicação determinista.', 'Consideração suficiente da história e das políticas.', 'Reconhecimento de todas as possibilidades técnicas.', 'Análise centrada em significados do lugar.'],0,['A frase transforma um elemento natural em destino social e ignora relações históricas, políticas e econômicas. Essa generalização é inadequada.', 'A frase não examina história nem políticas; atribui inevitabilidade ao clima.', 'Não há discussão das técnicas ou das escolhas dos grupos humanos.', 'Significados do lugar pertencem a outro tipo de pergunta. Aqui há uma causalidade natural tomada como absoluta.'],'Geografia clássica')
q('q08','l03','Qual formulação se aproxima da ideia de possibilidades historicamente mobilizadas?', ['O rio determina um único modo de viver.', 'Todas as sociedades agem sem qualquer limite natural.', 'Condições do meio são utilizadas de formas distintas por meio de técnicas e práticas sociais.', 'A natureza não participa da vida humana.'],2,['Essa formulação transforma o meio em destino único.', 'Possibilidades não significam ausência de condições ou limites.', 'A afirmação considera o meio, mas inclui técnicas e práticas na relação com ele. Essa é a chave da leitura possibilista apresentada.', 'A relação com a natureza continua relevante; ela não desaparece.'],'Geografia clássica')
q('q09','l03','Para estudar Ratzel e Vidal de la Blache, basta decorar duas frases que expliquem toda a obra de cada um.', ['Verdadeiro','Falso'],1,['As fórmulas ajudam na introdução, mas simplificam trajetórias e obras complexas. Uma questão pode exigir perceber essa limitação.', 'Use as referências como orientação inicial e evite caricaturas. Obras e contextos históricos precisam ser considerados.'],'Geografia clássica')

lesson('l04','Descrição e Geografia regional','O alcance e o limite do inventário',8,[
 text('Sob o nome “Geografia tradicional” são agrupadas tradições diversas. São recorrentes a descrição, a observação, a classificação e a diferenciação de áreas. A abordagem regional procura compreender combinações de características em determinados recortes, e não apenas listar elementos isolados.'),
 text('Na escola, uma prática tradicional frequentemente se expressa em inventários: enumerar rios, cidades, atividades econômicas e formas de relevo. Esse conhecimento pode ser útil. O limite aparece quando a aula para na enumeração e não investiga processos, conflitos e relações entre lugares.'),
 {'type':'compare','title':'Da descrição para a explicação','left':{'title':'Inventário','body':'A comunidade tem um rio, uma escola, uma estrada e uma feira.'},'right':{'title':'Problema geográfico','body':'Como as condições da estrada influenciam a circulação da produção e o acesso à escola ao longo do ano?'}},
 text('Comparar regiões exige declarar os critérios de recorte. Regiões climáticas e regiões definidas por redes urbanas podem ter limites diferentes. A ideia de região é uma forma de organização e interpretação do espaço, não uma caixa natural válida para qualquer pergunta.'),
 call('Não transforme descrição em inimiga','Observar e descrever fornecem evidências. Uma boa análise usa esses passos para construir explicações; não precisa abandonar os nomes e os fatos.')
], 'Descrição e classificação são úteis. A aprendizagem fica limitada quando o inventário substitui a investigação das relações espaciais.')
q('q10','l04','Qual situação caracteriza o limite de uma aula centrada exclusivamente no inventário?', ['Descrever como passo para investigar.', 'Comparar critérios de regionalização.', 'Listar elementos sem examinar relações ou processos.', 'Usar nomes de rios em uma explicação.'],2,['A descrição é um passo legítimo quando conduz a uma investigação.', 'Comparar critérios exige interpretação e supera uma simples lista.', 'O problema é parar na enumeração. O aluno não aprende como os elementos se relacionam ou por que se distribuem daquele modo.', 'Usar nomes é útil e não impede uma análise mais ampla.'],'Geografia tradicional')
q('q11','l04','Recortes regionais definidos por critérios diferentes podem apresentar limites diferentes.', ['Verdadeiro','Falso'],0,['A regionalização depende do problema e dos critérios utilizados. Clima e redes urbanas podem produzir recortes distintos.', 'Regiões não são limites únicos válidos para todos os assuntos. O critério precisa ser explicitado.'],'região')
q('q12','l04','Qual proposta articula descrição e explicação?', ['Copiar os nomes das estradas sem outras perguntas.', 'Identificar acessos e investigar como afetam a circulação da produção.', 'Abolir a observação da paisagem.', 'Memorizar um recorte regional como se fosse o único possível.'],1,['A cópia de nomes não articula elementos ou processos.', 'A proposta começa com uma observação e a usa para investigar relações espaciais. Descrição e explicação passam a trabalhar juntas.', 'Sem observar evidências, a interpretação perde uma base importante.', 'Critérios de recorte devem ser considerados e comparados.'],'Geografia tradicional')

lesson('l05','A perspectiva teórico-quantitativa','Padrões, modelos e medidas',9,[
 text('A Geografia teórico-quantitativa ganhou força a partir de meados do século XX. Busca explicar padrões de distribuição e organização espacial com modelos, hipóteses, relações matemáticas e procedimentos estatísticos. Uma influência importante é o neopositivismo. A finalidade não é apenas contar, mas construir e testar explicações.'),
 text('Imagine medir o tempo de viagem entre comunidades e escolas. Um mapa permite identificar concentração de trajetos longos; um modelo pode relacionar tempo, distância e acesso por estrada ou rio. Isso contribui para avaliar padrões espaciais.'),
 anim('quantitative','Distância e tempo não são a mesma coisa','Escolha uma rota para observar distâncias e tempos hipotéticos. Todos os valores desta animação são inventados para explicar o conceito.'),
 call('Potencial e limite','Medidas ajudam a comparar e testar hipóteses. Porém, uma média pode esconder desigualdades e um modelo depende de suas escolhas e pressupostos. É preciso perguntar quem ficou fora dos dados.'),
 text('No ensino, gráficos e estatísticas podem apoiar diferentes perspectivas. Usar um gráfico não torna toda aula “teórico-quantitativa”. A concepção se reconhece pelo papel explicativo dado aos modelos e pela forma de produzir conhecimento.')
], 'A perspectiva teórico-quantitativa enfatiza modelos e padrões espaciais. Estatísticas são úteis, mas precisam ser interpretadas com seus limites e pressupostos.')
q('q13','l05','Qual objetivo se aproxima mais da perspectiva teórico-quantitativa?', ['Testar um modelo sobre distribuição e distância entre serviços.', 'Investigar apenas memórias afetivas.', 'Afirmar que nenhum padrão pode ser estudado.', 'Listar topônimos sem relações.'],0,['A construção e o teste de modelos para explicar padrões espaciais é uma característica dessa perspectiva.', 'Memórias afetivas indicam uma pergunta mais próxima de abordagens do lugar vivido.', 'A perspectiva quantitativa busca justamente reconhecer e explicar padrões.', 'Um inventário sem relações não expressa o foco em modelos explicativos.'],'Geografia quantitativa')
q('q14','l05','Uma média de tempo de viagem é suficiente para afirmar que todos têm o mesmo acesso à escola.', ['Verdadeiro','Falso'],1,['Uma média pode ocultar trajetos muito diferentes. É necessário examinar a distribuição e quem está em cada condição.', 'A média resume o conjunto e pode esconder desigualdades. Compare grupos, trajetos e variações antes de concluir.'],'dados e modelos')
q('q15','l05','Uma pesquisa usa estatísticas para investigar desigualdades de mobilidade. Qual conclusão é adequada?', ['A pesquisa deixou automaticamente de ser crítica.', 'Todo gráfico define uma concepção teórica única.', 'As estatísticas podem apoiar a análise crítica, dependendo do problema e da interpretação.', 'Os números dispensam conhecer o contexto.'],2,['O uso de números não exclui perguntas críticas sobre desigualdade e poder.', 'O recurso, sozinho, não define a concepção que orienta a investigação.', 'Técnicas quantitativas podem ser mobilizadas em análises distintas. Examine o papel delas na explicação e o contexto investigado.', 'Os dados precisam de contexto, critérios e interpretação.'],'teoria e método')

lesson('l06','Geografias críticas','Espaço, poder e desigualdades',10,[
 text('O movimento de renovação crítica questiona explicações que tratam a organização do espaço como neutra ou desligada da história. Tem diferentes vertentes; o materialismo histórico e dialético é uma referência importante em muitas delas. Trabalho, produção, Estado, poder e desigualdade passam ao centro de várias investigações.'),
 text('O espaço é produzido e transformado socialmente. Estradas, moradias e áreas agrícolas materializam escolhas, técnicas, investimentos e conflitos. Por isso, a distribuição dos serviços não pode ser explicada apenas pelo relevo ou por decisões individuais isoladas.'),
 photo('ver-o-peso.jpg','Uma paisagem também tem relações de trabalho','O Ver-o-Peso, em Belém, pode ser estudado por sua forma visível e por relações de circulação, trabalho e acesso. As perguntas desta unidade são propostas de investigação, não conclusões sobre trabalhadores fotografados.','Fabio Gomes · Wikimedia Commons · CC BY-SA 4.0'),
 text('Milton Santos contribui para compreender o espaço por meio de relações indissociáveis entre objetos e ações. Uma estrada não é apenas uma forma: importa quem a utiliza, quais fluxos possibilita e que práticas e relações a acompanham. A separação entre materialidade e ação enfraquece a análise.'),
 call('Na sala de aula','Compare acesso à água, transporte ou equipamentos públicos em áreas distintas. Pergunte como se produziram as diferenças e que relações conectam os lugares. Evite trocar explicação fundamentada por uma opinião genérica.'),
 call('Crítica precisa de argumento','Uma aula não se torna crítica só por denunciar um problema. Ela precisa construir relações e explicações, usar conceitos e examinar evidências.', 'warning')
], 'Analisar criticamente é investigar a produção social do espaço, suas relações de poder e contradições. Não é apenas expressar indignação.')
q('q16','l06','Qual pergunta se aproxima mais de uma análise crítica do acesso ao transporte?', ['Qual é a cor dos ônibus?', 'Como decisões públicas e relações econômicas produzem acessos desiguais?', 'Qual clima torna desigualdade inevitável?', 'Quem consegue decorar mais linhas de ônibus?'],1,['A cor pode ser observada, mas não explica o acesso desigual.', 'A pergunta relaciona decisões, produção do espaço e desigualdades. Ela solicita uma explicação histórica e social.', 'Essa formulação naturaliza um problema que exige examinar relações sociais.', 'A memorização de linhas pode ajudar na localização, mas não investiga a produção da desigualdade.'],'Geografia crítica')
q('q17','l06','Criticar um problema, sem conceitos nem evidências, basta para desenvolver uma análise geográfica crítica.', ['Verdadeiro','Falso'],1,['Uma denúncia pode iniciar a discussão, mas precisa de relações explicativas e evidências para constituir análise.', 'A indignação não substitui a investigação. Conceitos, processos e evidências sustentam o argumento crítico.'],'Geografia crítica')
q('q18','l06','Na relação entre objetos e ações, uma estrada deve ser estudada:', ['Apenas como uma forma física.', 'Sem considerar os fluxos que possibilita.', 'Com sua materialidade e as práticas e relações que a utilizam.', 'Como algo separado da sociedade.'],2,['A forma física é relevante, mas isolá-la das práticas impede compreender seu funcionamento espacial.', 'Os fluxos são parte importante das ações relacionadas à estrada.', 'A estrada participa de uma organização espacial na qual materialidade e ações se relacionam. Uso, circulação e poder precisam entrar na explicação.', 'A estrada é construída e usada em relações sociais e condições naturais.'],'objetos e ações')

lesson('l07','A perspectiva humanística','Experiência e lugar vivido',8,[
 text('A Geografia humanística enfatiza experiências, percepções, sentidos e vínculos das pessoas com os lugares. A fenomenologia é uma referência importante. Yi-Fu Tuan é um autor associado a estudos de experiência, espaço e lugar. Não se trata de afirmar que tudo é opinião, mas de investigar modos de viver e significar o espaço.'),
 text('Uma feira pode ser um lugar de trabalho para alguém, um encontro familiar para outra pessoa e uma lembrança da infância para outra. Conhecer essas experiências amplia a interpretação do lugar e evita reduzir a cidade a coordenadas e estruturas materiais.'),
 anim('lived','O mesmo lugar, experiências diferentes','Toque nas pessoas da cena para ler relatos fictícios sobre a mesma praça. Nenhum relato representa automaticamente todas as pessoas de um grupo.'),
 call('Possibilidade de ensino','Mapas mentais, relatos de trajetos e entrevistas podem revelar sentidos do bairro. O professor pode comparar experiências e conectá-las a conceitos; não basta colecionar histórias.'),
 text('Sentimentos de pertencimento e afastamento podem coexistir. Um lugar familiar para uma pessoa pode ser hostil para outra. Perguntar por experiências diferentes ajuda a compreender a complexidade do lugar, sem apagar estruturas sociais.')
], 'A perspectiva humanística investiga experiência, percepção e significados do lugar. Os relatos precisam de interpretação e não representam todos os sujeitos automaticamente.')
q('q19','l07','Qual investigação tem maior proximidade com a perspectiva humanística?', ['Calcular apenas a média de distâncias.', 'Entender como moradores vivenciam e atribuem sentido ao bairro.', 'Decorar a lista dos bairros.', 'Atribuir costumes obrigatoriamente ao clima.'],1,['A medida pode ser útil, mas não investiga, por si, a experiência do lugar.', 'A pergunta procura a experiência, a percepção e os significados do lugar vivido, marcas dessa perspectiva.', 'A lista não revela os sentidos ou os vínculos das pessoas com o bairro.', 'Atribuir práticas ao clima de modo obrigatório é uma explicação determinista.'],'Geografia humanística')
q('q20','l07','Um relato sobre a feira representa necessariamente a experiência de todos os moradores.', ['Verdadeiro','Falso'],1,['Experiências variam. Um relato é uma fonte situada, não uma voz automática de toda a população.', 'Compare diferentes relatos e reconheça quem fala e em que contexto. A diversidade de experiências é parte da análise.'],'lugar vivido')
q('q21','l07','Para ensinar com mapas mentais, o professor deve:', ['Considerá-los retratos exatos e universais do bairro.', 'Descartar todas as diferenças entre desenhos.', 'Articular as representações dos alunos a perguntas e conceitos geográficos.', 'Usá-los somente como decoração.'],2,['Mapas mentais são representações situadas, com escolhas e sentidos, e não retratos universais.', 'As diferenças podem revelar experiências importantes para a investigação.', 'A mediação transforma as representações em oportunidade de aprendizagem. Os alunos podem comparar, interpretar e ampliar seus conhecimentos.', 'O recurso tem potencial conceitual quando integrado ao problema de estudo.'],'mediação')

lesson('l08','Abordagens culturais','Representações e diferenças',8,[
 text('As abordagens culturais examinam práticas, símbolos, identidades, representações e seus vínculos espaciais. Há distintas tradições na Geografia cultural. Parte das abordagens contemporâneas também pergunta quem produz representações e como elas se relacionam com poder e diferença.'),
 text('Uma imagem que apresenta a Amazônia apenas como floresta vazia é uma representação seletiva. Ela pode apagar cidades, comunidades indígenas, populações ribeirinhas e agricultores. Estudar a representação exige perguntar o que foi mostrado, o que foi omitido e com que efeitos.'),
 {'type':'compare','title':'Duas perguntas que se aproximam, mas não são idênticas','left':{'title':'Experiência do lugar','body':'Como uma pessoa vive a feira e que sentidos atribui a ela?'},'right':{'title':'Representação cultural','body':'Como a feira é mostrada em uma campanha turística e que grupos aparecem ou desaparecem?'}},
 call('Cultura não é uma lista fixa','Práticas mudam, são disputadas e variam dentro dos grupos. Evite representar “o amazônida”, “o indígena” ou “o agricultor” como personagens únicos e imutáveis.'),
 text('Na escola, fotografias, músicas e notícias podem ser comparadas para analisar representações do espaço. Humanística e cultural podem dialogar, mas não são sinônimos. Identifique qual problema orienta cada abordagem.')
], 'As abordagens culturais estudam práticas e representações espaciais, reconhecendo diversidade e disputas. Cultura não equivale a um conjunto imutável de costumes.')
q('q22','l08','Analisar quem aparece e quem é omitido em uma propaganda sobre a Amazônia mobiliza principalmente:', ['Uma pergunta sobre representações e relações de poder.', 'A memorização de capitais.', 'Um determinismo climático.', 'A recusa em interpretar imagens.'],0,['A representação seleciona sujeitos e aspectos do espaço. Investigar essa seleção e seus efeitos articula cultura, espaço e poder.', 'A pergunta não se limita a nomes e localizações.', 'O problema não atribui práticas sociais ao clima; examina uma representação.', 'A atividade exige justamente interpretar a produção da imagem.'],'Geografia cultural')
q('q23','l08','Práticas culturais podem mudar e apresentar diferenças dentro de um mesmo grupo.', ['Verdadeiro','Falso'],0,['As práticas são históricas e diversas. Reconhecer mudanças evita estereótipos e simplificações.', 'Tratar grupos como homogêneos e imutáveis reduz sua complexidade. A análise cultural precisa considerar mudanças e disputas.'],'Geografia cultural')
q('q24','l08','Qual proposta evita estereótipos sobre populações da Amazônia?', ['Apresentar uma única imagem como retrato de todos.', 'Afirmar que todos mantêm os mesmos costumes.', 'Comparar fontes e experiências de sujeitos distintos.', 'Excluir cidades de qualquer representação regional.'],2,['Uma imagem não representa a totalidade das experiências de uma região.', 'A homogeneização apaga diferenças internas e mudanças históricas.', 'Fontes e experiências diversas permitem examinar escolhas de representação e reconhecer diferenças entre sujeitos e lugares.', 'Excluir cidades constrói uma representação seletiva e incompleta.'],'representações')

lesson('l09','Geografia escolar e mediação','Do conhecimento vivido ao conceito',9,[
 text('Geografia escolar não é apenas uma versão encurtada da Geografia acadêmica. Ela seleciona e organiza conhecimentos para finalidades educativas, em condições escolares e em diálogo com alunos, currículos e saberes docentes. A ciência é uma referência fundamental, mas a aprendizagem demanda mediação.'),
 text('Na perspectiva histórico-cultural e em propostas socioconstrutivistas, o aluno participa ativamente da construção do conhecimento. O professor tem ação intencional: oferece conceitos, problemas, linguagens e intervenções para ampliar as explicações dos estudantes.'),
 anim('mediation','A conversa precisa avançar','Percorra os passos: relato cotidiano, pergunta do professor, relação conceitual e explicação mais ampla.'),
 text('Exemplo hipotético de uma comunidade de Garrafão do Norte: um aluno diz que a estrada “fica ruim” no período chuvoso. O professor pergunta como isso afeta deslocamentos e circulação da produção, solicita observações e relaciona o caso a redes e acesso. O relato passa a sustentar uma explicação geográfica, sem ser descartado.'),
 call('Participação ativa não é abandono','O estudante não precisa descobrir tudo sozinho. Mediação, orientação, exposição conceitual e comparação de fontes podem ajudá-lo a reconstruir sua explicação.'),
 text('Avaliar é observar o que mudou na compreensão: o aluno passou a relacionar fenômenos? Usa conceitos com sentido? Justifica uma hipótese com evidências? Uma tarefa movimentada não garante esses avanços.')
], 'A mediação articula experiência cotidiana e conhecimento conceitual. O professor intervém de forma intencional; o aluno constrói e amplia explicações.',{'type':'order','title':'Organize uma sequência de mediação','items':['Levantar como os estudantes percebem os trajetos.','Formular uma pergunta sobre acesso e circulação.','Comparar fontes e mobilizar conceitos geográficos.','Construir uma explicação e avaliar o que se aprendeu.']})
q('q25','l09','Qual intervenção indica mediação conceitual?', ['Aceitar qualquer relato sem discussão.', 'Descartar o cotidiano e exigir somente definições.', 'Relacionar relatos de trajetos a conceitos de redes e acesso.', 'Deixar que o aplicativo explique tudo sem professor.'],2,['O relato é um ponto de partida. Sem intervenções, ele pode não avançar para uma explicação conceitual.', 'O cotidiano pode fornecer referências para a aprendizagem; não precisa ser descartado.', 'A intervenção ajuda o aluno a ampliar sua interpretação e a construir relações geográficas a partir da experiência.', 'A tecnologia é recurso de apoio. A mediação e as decisões de ensino continuam relevantes.'],'mediação')
q('q26','l09','Geografia escolar é somente a redução do volume de conteúdos da Geografia acadêmica.', ['Verdadeiro','Falso'],1,['A Geografia escolar tem finalidades educativas, organização curricular e condições de aprendizagem específicas.', 'Ela dialoga com a ciência, mas envolve seleção, organização, mediação e finalidades escolares. Não se explica apenas por diminuir conteúdo.'],'Geografia escolar')
q('q27','l09','Uma atividade foi divertida e muito movimentada. O que é necessário verificar para avaliar sua aprendizagem?', ['Somente a quantidade de cliques.', 'Se os alunos ampliaram explicações e mobilizaram conceitos e evidências.', 'Somente o volume do som.', 'Se todos usaram o mesmo telefone.'],1,['Cliques informam uso, mas não demonstram compreensão conceitual.', 'A aprendizagem precisa aparecer na interpretação: relações mais claras, uso de conceitos e argumentos sustentados por evidências.', 'O som não informa o que foi compreendido.', 'O tipo de telefone não mede a construção do conhecimento geográfico.'],'avaliação')

lesson('l10','Raciocinar geograficamente','Localizar, relacionar e explicar',9,[
 text('Para raciocinar geograficamente, não basta identificar um fenômeno. É preciso examinar localização, distribuição, extensão, conexões e diferenças, considerando a escala de análise. Esses princípios ajudam a organizar perguntas e a construir explicações.'),
 {'type':'table','title':'Perguntas que fazem avançar','headers':['Operação','Pergunta'],'rows':[['Localização','Onde acontece? A posição é absoluta ou relativa?'],['Distribuição','Está concentrado, disperso ou ausente em certas áreas?'],['Conexão','Quais fluxos e relações conectam esses lugares?'],['Comparação','O que é semelhante e diferente? Quais critérios uso?'],['Escala','Que relações aparecem no bairro, no município ou na rede regional?']]},
 anim('scale','O lugar está ligado a outros lugares','Alterne a escala para observar a relação hipotética entre escola, comunidade, município e circuitos regionais de circulação.'),
 text('O local não é uma ilha. A circulação de alimentos de uma comunidade pode depender de decisões municipais, de estradas estaduais e de mercados em outras cidades. Mudar a escala permite perceber relações que não aparecem em uma observação restrita.'),
 call('Uma confusão comum','Escala cartográfica expressa a relação entre distâncias no mapa e no terreno. Escala geográfica diz respeito ao recorte e ao nível de análise dos processos. Aqui, o foco é a análise dos processos, não um cálculo cartográfico.'),
 text('No ensino, um bom percurso passa da pergunta ao levantamento de evidências, à comparação, à mobilização de conceitos e à explicação. Não precisa seguir um roteiro rígido em toda aula, mas deve dar sentido às atividades.')
], 'Raciocínio geográfico articula operações e conceitos para explicar relações espaciais. A escala de análise muda as relações que se tornam visíveis.')
q('q28','l10','Ao relacionar uma feira local a redes de transporte e mercados regionais, a investigação:', ['Trata o lugar como isolado.', 'Articula conexões e escalas de análise.', 'Abandona qualquer localização.', 'Usa exclusivamente escala cartográfica numérica.'],1,['A proposta explicita relações com outros lugares; faz o contrário de isolar.', 'Os fluxos conectam o lugar a redes mais amplas. Diferentes escalas ajudam a perceber essas relações.', 'A localização continua relevante para compreender posições e conexões.', 'A pergunta refere-se à escala geográfica de análise, não apenas à proporção do mapa.'],'escalas')
q('q29','l10','Escala geográfica e escala cartográfica designam exatamente a mesma coisa.', ['Verdadeiro','Falso'],1,['A escala cartográfica trata de proporção de distâncias; a geográfica trata do recorte e do nível de análise.', 'Os conceitos se relacionam, mas não são idênticos. Distingui-los ajuda a interpretar perguntas sobre processos espaciais.'],'escalas')
q('q30','l10','Qual questão investiga a distribuição de um fenômeno?', ['Como os serviços se concentram ou se dispersam entre bairros?', 'Qual é a cor da capa do atlas?', 'Quem escreveu mais nomes de capitais?', 'Quantas sílabas tem o nome do município?'],0,['Concentração e dispersão são formas de distribuição espacial. A pergunta pode conduzir à investigação de diferenças de acesso.', 'A capa do atlas não informa distribuição de serviços.', 'A memorização de nomes não examina o padrão espacial do fenômeno.', 'Sílabas não são um critério para investigar a distribuição dos serviços.'],'raciocínio geográfico')

lesson('l11','Uma paisagem, várias perguntas','Laboratório do Ver-o-Peso',8,[
 photo('belem-feira.jpg','Observe antes de escolher a explicação','Use a fotografia como ponto de partida. Você pode observar formas e práticas visíveis; condições de renda e relações de poder exigem outras fontes, não podem ser deduzidas pela aparência das pessoas.','Cayambe · Wikimedia Commons · CC BY-SA 3.0'),
 anim('lenses','Troque a lente, mude a pergunta','Selecione uma perspectiva e compare o que ela destaca na mesma cena. A animação é uma síntese didática, não uma classificação automática de aulas.'),
 {'type':'table','title':'Quatro caminhos de investigação','headers':['Foco','Pergunta possível'],'rows':[['Descrição e diferenciação de áreas','Quais elementos e usos caracterizam a paisagem?'],['Modelos e padrões','Como variam fluxos e distâncias de abastecimento?'],['Produção social e poder','Que relações de trabalho e decisões organizam o circuito?'],['Experiência e significados','Como diferentes pessoas vivenciam e representam o lugar?']]},
 text('Nenhuma fotografia revela, sozinha, todos esses processos. Para conhecer o circuito de abastecimento, precisamos de informações sobre origem dos produtos e circulação. Para estudar experiências, podemos ouvir sujeitos. Para examinar políticas e trabalho, buscamos documentos e outras evidências.'),
 call('Concepções podem dialogar','Combinar dados, relatos e fotografias pode enriquecer a análise. A combinação precisa ter um problema comum e critérios claros; não é necessário encaixar toda atividade em uma única etiqueta.')
], 'Uma mesma paisagem comporta problemas distintos. Reconheça o foco da pergunta, a explicação buscada e as fontes necessárias.',{'type':'match','title':'Qual pergunta combina com cada foco?','pairs':[['Que formas e usos caracterizam a feira?','Descrição da paisagem'],['Como se distribuem os fluxos de abastecimento?','Padrões e modelos'],['Que relações organizam trabalho e acesso?','Produção social e poder'],['Que sentidos as pessoas atribuem à feira?','Experiência do lugar']]})
q('q31','l11','É possível inferir a renda exata das pessoas apenas por uma fotografia da feira.', ['Verdadeiro','Falso'],1,['A aparência não é base suficiente para esse dado. Seriam necessárias fontes e procedimentos apropriados.', 'A fotografia mostra uma seleção de aspectos visíveis. Evite deduzir renda, identidade ou relações sociais completas apenas pela aparência.'],'fontes e evidências')
q('q32','l11','Uma investigação compara fluxos, entrevista trabalhadores e examina decisões públicas. Qual cuidado dá coerência a essa combinação?', ['Ter um problema comum e critérios para interpretar as fontes.', 'Usar muitas ferramentas sem qualquer pergunta.', 'Supor que todas as fontes respondem tudo.', 'Eliminar todos os conceitos.'],0,['Fontes distintas podem responder partes de um problema. Critérios de análise permitem articulá-las sem confundir seus alcances.', 'Acumular ferramentas não garante uma investigação coerente.', 'Cada fonte tem limites e responde melhor a certas perguntas.', 'Os conceitos ajudam a relacionar e interpretar as evidências.'],'fontes e evidências')
q('q33','l11','“Quais sentidos a feira assume para diferentes pessoas?” é uma pergunta principalmente ligada a:', ['Experiência e significados do lugar.', 'Determinismo climático.', 'Memorização exclusiva de topônimos.', 'Cálculo obrigatório de escala cartográfica.'],0,['A pergunta investiga o lugar vivido e a diversidade de experiências, aproximando-se de uma leitura humanística.', 'Ela não atribui comportamentos ao clima.', 'Os sentidos ultrapassam o reconhecimento de nomes.', 'Não se trata de uma proporção entre distâncias no mapa e no terreno.'],'Geografia humanística')

lesson('l12','Como levar isso para a prova','Compare, justifique e exemplifique',8,[
 text('Em uma questão, leia o que o professor ou pesquisador está tentando explicar. Identifique o objeto, os conceitos, as relações e o papel do aluno. Só depois associe a proposta a uma perspectiva. Palavras isoladas, como “mapa” ou “tecnologia”, não são suficientes.'),
 listing('Um roteiro de leitura',['Qual é o problema: inventário, padrão, desigualdade, experiência ou representação?', 'Que explicação é oferecida: causa natural única, modelo, produção social ou significados?', 'Que evidências sustentam a interpretação?', 'Como o ensino transforma a experiência em compreensão conceitual?']),
 {'type':'compare','title':'Reconheça o raciocínio incompleto','left':{'title':'Associação apressada','body':'Usou fotografia, então a aula é humanística.'},'right':{'title':'Leitura fundamentada','body':'A aula analisa sentidos atribuídos pelos moradores e os relaciona ao lugar vivido; a fotografia é um dos recursos.'}},
 call('Redação também precisa de treino','No edital enviado, a prova inclui 20 questões objetivas e uma redação de até 20 linhas. As duas partes têm peso 0,50. Use a oficina de escrita do app para defender uma ideia, explicar um conceito e aplicar a um caso.'),
 text('Exemplo de estrutura: apresente uma tese sobre a finalidade do ensino; explique a concepção ou conceito que sustenta a tese; analise uma situação didática; conclua conectando a atividade à aprendizagem. Não existe texto mágico que sirva para qualquer tema.'),
 call('Seu próximo passo','Faça o simulado da unidade. Depois revise os erros e escreva uma resposta curta. Os exercícios são autorais: não são questões oficiais nem previsão do que será cobrado.')
], 'Na prova, reconheça as relações que sustentam a proposta. Na redação, articule tese, conceito e exemplo didático, respeitando o tema e o limite de linhas.',{'type':'order','title':'Organize um argumento didático','items':['Apresentar uma tese que responda ao tema.','Explicar um conceito relevante.','Analisar uma situação de ensino com esse conceito.','Concluir relacionando ensino e aprendizagem.']})
q('q34','l12','Uma questão informa apenas que a aula usou fotografias. Qual é a decisão mais adequada?', ['Classificá-la imediatamente como humanística.', 'Classificá-la imediatamente como crítica.', 'Examinar o problema e a interpretação, pois o recurso não basta.', 'Declarar que fotografias não têm função didática.'],2,['Fotografias podem ser usadas com diferentes objetivos. Falta saber o problema investigado.', 'Uma análise crítica depende das relações construídas, não apenas de uma foto.', 'Essa cautela evita uma associação automática entre ferramenta e teoria. Procure a finalidade, os conceitos e a explicação.', 'Fotografias podem apoiar a observação, a comparação e a interpretação do espaço.'],'teoria e método')
q('q35','l12','Uma redação sobre ensino de Geografia é fortalecida por:', ['Listas de autores sem relação com o tema.', 'Tese, conceito explicado e exemplo didático analisado.', 'Opiniões sem justificativa.', 'Uma conclusão que ignora a aprendizagem.'],1,['Os autores devem contribuir para o argumento; uma lista não demonstra compreensão.', 'A articulação torna visível a relação entre fundamentação e prática. O exemplo precisa ser analisado, e não apenas mencionado.', 'Justificativas e relações conceituais sustentam o argumento.', 'A aprendizagem é central em um tema sobre ensino. A conclusão deve retomar a tese.'],'redação')
q('q36','l12','Os exercícios do aplicativo substituem questões oficiais e garantem os temas da próxima prova.', ['Verdadeiro','Falso'],1,['São exercícios autorais de estudo. Não há garantia de repetição ou de previsão de cobrança.', 'Eles treinam a compreensão do conteúdo programático. Questões oficiais, quando disponíveis, são outra fonte de preparação.'],'preparação')

final_specs=[
('Em uma aula, alunos apenas repetem nomes de rios e relevos. Qual mudança amplia a aprendizagem?', ['Relacionar relevo, circulação e formas de ocupação em um problema.','Aumentar a lista sem discutir relações.','Retirar toda observação.','Afirmar que localizar nunca é útil.'],0,'descrição e explicação'),
('“A localização da escola explica sozinha todas as diferenças de aprendizagem”. Qual leitura é adequada?', ['Aceitar sem analisar.','Examinar outras relações sociais, condições de acesso e políticas.','Trocar localização por clima como causa única.','Abandonar qualquer análise espacial.'],1,'sociedade e natureza'),
('Qual proposta usa um modelo para investigar um padrão espacial?', ['Registrar memórias sem outro objetivo.','Copiar nomes de rios.','Testar relações entre distância, tempo e distribuição de serviços.','Atribuir culturas ao clima de forma inevitável.'],2,'Geografia quantitativa'),
('Uma abordagem crítica de uma estrada considera:', ['Somente a largura.','A materialidade, os fluxos, as decisões e as relações de poder.','Somente o nome.','Somente o tipo de tinta da sinalização.'],1,'Geografia crítica'),
('Ao investigar sentimentos de pertencimento ao bairro, qual foco predomina?', ['Experiência e significados do lugar.','Causa climática única.','Inventário exclusivo de nomes.','Escala cartográfica numérica.'],0,'Geografia humanística'),
('Um vídeo sobre a Amazônia omite cidades e sujeitos diversos. Que análise é pertinente?', ['Aceitar que a imagem mostra tudo.','Investigar a seleção da representação e seus efeitos.','Concluir que cultura nunca muda.','Deduzir identidades pela aparência.'],1,'Geografia cultural'),
('O que caracteriza uma mediação que parte do cotidiano?', ['Encerrar a aula no relato espontâneo.','Descartar a experiência dos alunos.','Articular experiências, perguntas, conceitos e explicações.','Retirar a intervenção docente.'],2,'mediação'),
('Qual afirmação distingue recurso e teoria?', ['Todo mapa é quantitativo.','Todo aplicativo é crítico.','A concepção depende das perguntas e relações construídas.','Uma saída de campo define automaticamente a teoria.'],2,'teoria e método'),
('O limite de uma explicação ambiental determinista é:', ['Reconhecer qualquer condição natural.','Transformar condição natural em destino e apagar mediações sociais.','Considerar relações históricas.','Comparar técnicas diferentes.'],1,'Geografia clássica'),
('A noção de possibilidades na relação sociedade-natureza envolve:', ['Ausência de limites naturais.','Um destino único para cada clima.','Condições, práticas e técnicas historicamente mobilizadas.','Negação da natureza.'],2,'Geografia clássica'),
('Por que a média de deslocamento deve ser interpretada com cuidado?', ['Porque médias nunca têm utilidade.','Porque pode esconder diferenças entre grupos e trajetos.','Porque demonstra igualdade automaticamente.','Porque torna contexto desnecessário.'],1,'dados e modelos'),
('Ao mudar da comunidade para a rede regional, o estudo:', ['Pode revelar conexões invisíveis no recorte restrito.','Prova que o local não importa.','Calcula necessariamente uma escala cartográfica.','Elimina toda observação.'],0,'escalas'),
('Qual avaliação mostra um avanço conceitual?', ['O aluno clicou em muitos botões.','O aluno decorou a cor da tela.','O aluno explica relações entre acesso, circulação e organização espacial.','O aluno escreveu o nome do app.'],2,'avaliação'),
('Para estudar representações culturais, é importante:', ['Tratar todo grupo como homogêneo.','Comparar quem representa, o que aparece e o que é omitido.','Apagar diferenças internas.','Supor costumes imutáveis.'],1,'representações'),
('Geografia escolar e Geografia acadêmica:', ['São idênticas em suas finalidades e condições.','Não têm qualquer relação.','Dialogam, mas a escolar organiza conhecimentos para finalidades educativas.','Diferem apenas pelo tamanho do livro.'],2,'Geografia escolar'),
('Uma descrição regional ganha força explicativa quando:', ['Explicita critérios e relaciona processos.','Oculta os critérios de recorte.','Apresenta o recorte como único possível.','Substitui evidências por uma lista maior.'],0,'região'),
('Qual frase evita reduzir uma perspectiva a caricatura?', ['Ratzel pode ser explicado completamente por uma frase.','Toda Geografia crítica tem exatamente o mesmo método.','As correntes têm diversidade interna e precisam de contexto histórico.','Toda experiência individual representa a população inteira.'],2,'história do pensamento'),
('Qual conduta é adequada ao usar uma fotografia como fonte?', ['Deduzir renda exata pelo rosto.','Reconhecer a seleção do registro e procurar fontes para processos não visíveis.','Afirmar que ela revela toda a história.','Recusar qualquer observação.'],1,'fontes e evidências'),
('Um argumento sobre ensino de Geografia deve:', ['Relacionar tese, conceito e situação didática.','Apenas citar autores sem explicar.','Ignorar o tema.','Substituir justificativa por indignação.'],0,'redação'),
('Qual combinação pode ser coerente em uma investigação?', ['Mapas, dados e relatos articulados ao mesmo problema.','Muitas ferramentas sem pergunta comum.','Uma única fonte tomada como resposta para tudo.','Técnicas escolhidas sem objetivo de aprendizagem.'],0,'fontes e evidências')]
for i,(stem,options,answer,tag) in enumerate(final_specs,1):
    good='A alternativa articula a ideia central trabalhada na unidade. '+{
    'descrição e explicação':'A observação ganha sentido quando permite explicar relações e processos.',
    'sociedade e natureza':'Uma condição espacial não substitui a investigação de outras relações relevantes.',
    'Geografia quantitativa':'Modelos ajudam a construir e testar explicações sobre padrões espaciais.',
    'Geografia crítica':'A produção social do espaço envolve formas, ações, decisões e relações de poder.',
    'Geografia humanística':'Experiências e vínculos ajudam a interpretar os sentidos do lugar vivido.',
    'Geografia cultural':'Representações são seletivas e podem apagar sujeitos, práticas e espaços.',
    'mediação':'O cotidiano é ponto de partida para ampliar a compreensão com intervenção intencional.',
    'teoria e método':'O recurso não define, sozinho, a concepção que orienta a proposta.',
    'Geografia clássica':'Natureza, técnicas e relações históricas precisam ser articuladas, evitando destinos sociais inevitáveis.',
    'dados e modelos':'A distribuição e os contextos dos dados precisam ser examinados além de uma medida resumida.',
    'escalas':'Escalas de análise permitem investigar diferentes relações entre lugares.',
    'avaliação':'O uso de conceitos para explicar relações é uma evidência de aprendizagem.',
    'representações':'Cultura é histórica, diversa e atravessada por disputas de representação.',
    'Geografia escolar':'Finalidades educativas e mediação tornam a Geografia escolar uma organização específica do conhecimento.',
    'região':'Os critérios devem ser explicitados e o recorte precisa servir à pergunta de estudo.',
    'história do pensamento':'As denominações introdutórias não descrevem toda a complexidade de cada tradição.',
    'fontes e evidências':'Fontes têm alcances e limites; sua articulação precisa de critérios.',
    'redação':'Explicar o conceito e analisar o exemplo fortalece a justificativa da tese.'}[tag]
    wrong=[]
    for oi,option in enumerate(options):
        if oi==answer:wrong.append(good)
        else:wrong.append('Reveja esta proposta: '+option+' Essa leitura restringe ou distorce a análise. '+good.split('. ',1)[1])
    q('f%02d'%i,'l12',stem,options,answer,wrong,tag,True)

